    <!-- Testimonial Script -->
    <script>
        const testimonialSlider = document.getElementById('testimonial-slider');
        const testimonialTrack = document.getElementById('testimonial-track');
        const testimonialSlides = document.querySelectorAll('#testimonial-track .slide');
        const testimonialPrev = document.getElementById('testimonial-prev');
        const testimonialNext = document.getElementById('testimonial-next');
        const testimonialDots = document.getElementById('testimonial-dots');

        let testimonialIndex = 0;
        const testimonialVisibleDots = 3;
        const testimonialTotalSlides = testimonialSlides.length;

        function updateTestimonialDots() {
            const currentDotGroup = Math.floor(testimonialIndex / testimonialVisibleDots);
            testimonialDots.innerHTML = '';
            for (let i = 0; i < testimonialVisibleDots; i++) {
                const dotIndex = currentDotGroup * testimonialVisibleDots + i;
                if (dotIndex >= testimonialTotalSlides) break;
                const dot = document.createElement('div');
                dot.className = 'h-[12px] rounded-full bg-gradient-to-r from-[#7C3BAF] to-[#E61C42] transition-all duration-300';
                dot.style.width = dotIndex === testimonialIndex ? '70px' : '28px';
                dot.style.opacity = dotIndex === testimonialIndex ? '1' : '0.5';
                testimonialDots.appendChild(dot);
            }
        }

        function updateTestimonialSlider() {
            testimonialTrack.style.transform = `translateX(-${testimonialIndex * 100}%)`;
            updateTestimonialDots();
        }

        testimonialNext.addEventListener('click', () => {
            testimonialIndex = (testimonialIndex + 1) % testimonialTotalSlides;
            updateTestimonialSlider();
        });

        testimonialPrev.addEventListener('click', () => {
            testimonialIndex = (testimonialIndex - 1 + testimonialTotalSlides) % testimonialTotalSlides;
            updateTestimonialSlider();
        });

        updateTestimonialSlider();
        // Auto-slide every 2 seconds
        setInterval(() => {
            testimonialIndex = (testimonialIndex + 1) % testimonialTotalSlides;
            updateTestimonialSlider();
        }, 2000);
    </script>
</section>


